7	// Commandment 3: a custom data type can never be at the root of the data type folder.
8	// Built-in data types are grouped under /Umbraco/<editorAlias>, custom ones under /Custom/<editorAlias>.
9	public class DataTypeOrganizationService(
10	    IDataTypeService dataTypeService,
11	    IDataTypeContainerService containerService)
12	{
13	    private const string CustomFolderName = "Custom";
14	    private const string BuiltInFolderName = "Umbraco";
15	
16	    public async Task<int> OrganizeAllAsync()
17	    {
18	        var all = await dataTypeService.GetAllAsync();
19	        var organized = 0;
20	        foreach (var dataType in all.Where(dt => dt.ParentId == -1))
21	        {
22	            if (await OrganizeAsync(dataType))
23	                organized++;
24	        }
25	
26	        return organized;
27	    }
