            <p class="text-sm font-semibold uppercase tracking-widest text-indigo-600">The MCP Blog</p>
            <h1 class="mt-2 text-4xl font-bold tracking-tight">@Model.Title</h1>
            <p class="mt-3 max-w-2xl text-lg text-slate-600">@Model.Intro</p>
        </div>
    </header>
    <main class="mx-auto max-w-5xl px-4 py-10">
        @await Html.GetBlockGridHtmlAsync(Model, "body")
