                            <a href="@post.Url()">
                                <img src="@post.ListingImage.GetCropUrl(width: 800, height: 450)" alt="@post.ListingImage.Name" class="aspect-video w-full object-cover" />
                            </a>
                        }
                        <div class="flex flex-1 flex-col p-6">
                            <time datetime="@post.PublishDate.ToString("yyyy-MM-dd")" class="text-sm text-slate-500">@post.PublishDate.ToString("MMMM d, yyyy")</time>
                            <h3 class="mt-2 text-xl font-semibold">
                                <a href="@post.Url()" class="hover:text-indigo-600">@post.Title</a>
                            </h3>
                            <p class="mt-2 flex-1 text-slate-600">@post.Excerpt</p>
                            <a href="@post.Url()" class="mt-4 text-sm font-semibold text-indigo-600 hover:underline">Read post →</a>
                        </div>
                    </article>
                }
            </div>
        </section>
    </main>
    <footer class="border-t border-slate-200 bg-white">
        <div class="mx-auto max-w-5xl px-4 py-6 text-sm text-slate-500">
