</div>

@model Umbraco.Bench.Umbraco.Models.Blocks.ImageBlockModel

<figure class="my-8 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
	<img src="@Model.ImageUrl" alt="@Model.ImageName" class="aspect-video w-full object-cover" />
	@if (!string.IsNullOrWhiteSpace(Model.Caption))
	{
		<figcaption class="px-4 py-3 text-sm text-slate-500">@Model.Caption</figcaption>
	}
</figure>

