@using Umbraco.Cms.Core.Models.Blocks
@using Umbraco.Bench.Umbraco.Models
@using Umbraco.Bench.Umbraco.Models.Blocks
@inherits UmbracoViewPage<BlockGridItem<RichTextBlock>>
@{
	var model = new RichTextBlockModel
	{
		Html = Model.Content.Text?.ToHtmlString() ?? string.Empty,
	};
}
@await Component.InvokeAsync("RichTextBlock", new { model })

@using Umbraco.Cms.Core.Models.Blocks
@using Umbraco.Bench.Umbraco.Models
@using Umbraco.Bench.Umbraco.Models.Blocks
@inherits UmbracoViewPage<BlockGridItem<ImageBlock>>
@{
	var image = Model.Content.Image;
	var model = new ImageBlockModel
	{
		ImageUrl = image?.GetCropUrl(width: 1600) ?? string.Empty,
		ImageName = image?.Name,
		Caption = Model.Content.Caption ?? string.Empty,
	};
}
@await Component.InvokeAsync("ImageBlock", new { model })

